/**
 * Durable execution history for hosted architecture-v2 sessions.
 *
 * Entries are session-scoped and bounded. The host writes a running entry at
 * turn start, then records completion or process failure. Persistence errors
 * never change the hosted execution response.
 */
import { cursorHostedFiles } from "../files-backends/cursor-hosted.js";
import { agentSdkStorageKeys } from "../storage-protocol.js";
import { resolveApiKeySync } from "./cursor/credentials.js";
import { describeError } from "./describe-error.js";
import { isRecord } from "./is-record.js";
import { isCursorManagedV2Hosting, resolveAgentV2Hosting } from "./v2-hosting.js";
export const SESSION_RUN_LOG_VERSION = 1;
/** Last N log-ring lines kept on each execution. */
export const SESSION_RUN_LOG_MAX_ENTRIES = 200;
/** Per-line cap so a runaway logger cannot blow the document. */
export const SESSION_RUN_LOG_MAX_LINE_CHARS = 4096;
/** Continuations are FIFO; keep a bounded history for the session UI. */
export const SESSION_RUN_LOG_MAX_EXECUTIONS = 20;
const MAX_ERROR_MESSAGE_CHARS = 4096;
const MAX_ERROR_STACK_CHARS = 16_384;
const MAX_DOCUMENT_CHARS = 512 * 1024;
/** Crash-handler flush must not block `process.exit`. */
export const SESSION_RUN_FATAL_FLUSH_TIMEOUT_MS = 2_000;
function isSessionRunAbortReason(value) {
    return (value === "signal_abort" ||
        value === "runner_cancelled" ||
        value === "runner_error" ||
        value === "execute_throw" ||
        value === "process_exit" ||
        value === "uncaught_exception" ||
        value === "unhandled_rejection");
}
let fatalFlush;
/**
 * Install the process-level crash flush. One process has one active hosted
 * server.
 */
export function registerSessionRunFatalFlush(flush) {
    fatalFlush = flush;
}
export function unregisterSessionRunFatalFlush() {
    fatalFlush = undefined;
}
/**
 * Await the registered crash flush, bounded so a hung store cannot prevent
 * `process.exit`. Soft-fail.
 */
export async function flushSessionRunFatal(error) {
    if (fatalFlush === undefined) {
        return;
    }
    await Promise.race([
        fatalFlush(error).catch(() => undefined),
        new Promise((resolve) => {
            setTimeout(resolve, SESSION_RUN_FATAL_FLUSH_TIMEOUT_MS);
        }),
    ]);
}
function boundedText(value, max) {
    return value.length > max ? `${value.slice(0, max)}…` : value;
}
function boundedOptionalText(value, max) {
    if (value === undefined || value.length === 0) {
        return undefined;
    }
    return boundedText(value, max);
}
export function serializeSessionRunError(error) {
    if (error instanceof Error) {
        const stack = boundedOptionalText(error.stack, MAX_ERROR_STACK_CHARS);
        return {
            name: boundedText(error.name.length > 0 ? error.name : "Error", 128),
            message: boundedText(error.message, MAX_ERROR_MESSAGE_CHARS),
            ...(stack === undefined ? {} : { stack }),
        };
    }
    return {
        name: "Error",
        message: boundedText(String(error), MAX_ERROR_MESSAGE_CHARS),
    };
}
export function snapshotSessionRunLogs(entries) {
    const tail = entries.slice(-SESSION_RUN_LOG_MAX_ENTRIES);
    return tail.map((entry) => ({
        index: entry.index,
        at: entry.at,
        line: boundedText(entry.line, SESSION_RUN_LOG_MAX_LINE_CHARS),
    }));
}
function decodeSinkBody(body) {
    return body instanceof Uint8Array ? body : body.body;
}
function parseError(value) {
    if (!isRecord(value)) {
        return undefined;
    }
    const name = typeof value.name === "string" ? value.name : "";
    const message = typeof value.message === "string" ? value.message : "";
    const stack = typeof value.stack === "string" ? value.stack : undefined;
    return {
        name,
        message,
        ...(stack === undefined ? {} : { stack }),
    };
}
function parseLogs(value) {
    if (!Array.isArray(value)) {
        return [];
    }
    const logs = [];
    for (const entry of value) {
        if (!isRecord(entry)) {
            continue;
        }
        if (typeof entry.index !== "number" ||
            typeof entry.at !== "string" ||
            typeof entry.line !== "string") {
            continue;
        }
        logs.push({ index: entry.index, at: entry.at, line: entry.line });
    }
    return logs;
}
function parseExecution(value) {
    if (!isRecord(value)) {
        return undefined;
    }
    const executionId = typeof value.executionId === "string" ? value.executionId : undefined;
    const writtenAt = typeof value.writtenAt === "string" ? value.writtenAt : undefined;
    const sessionId = typeof value.sessionId === "string" ? value.sessionId : undefined;
    const turnStatus = typeof value.turnStatus === "string" ? value.turnStatus : undefined;
    const durationMs = typeof value.durationMs === "number" && Number.isFinite(value.durationMs)
        ? value.durationMs
        : undefined;
    if (executionId === undefined ||
        executionId.length === 0 ||
        writtenAt === undefined ||
        sessionId === undefined ||
        turnStatus === undefined ||
        turnStatus.length === 0 ||
        durationMs === undefined ||
        durationMs < 0) {
        return undefined;
    }
    const rawAbortReason = typeof value.abortReason === "string" ? value.abortReason : undefined;
    const abortReason = rawAbortReason !== undefined && isSessionRunAbortReason(rawAbortReason)
        ? rawAbortReason
        : undefined;
    const message = typeof value.message === "string" ? value.message : undefined;
    const error = parseError(value.error);
    return {
        executionId,
        writtenAt,
        sessionId,
        turnStatus,
        durationMs,
        abortReason,
        ...(message === undefined ? {} : { message }),
        ...(error === undefined ? {} : { error }),
        ...(value.processDeath === true ? { processDeath: true } : {}),
        logs: parseLogs(value.logs),
    };
}
export function lastFailureFromExecutions(executions) {
    const latest = executions.at(-1);
    if (latest === undefined || latest.turnStatus === "finished") {
        return undefined;
    }
    return {
        executionId: latest.executionId,
        writtenAt: latest.writtenAt,
        turnStatus: latest.turnStatus,
        ...(latest.abortReason === undefined ? {} : { abortReason: latest.abortReason }),
        ...(latest.message === undefined ? {} : { message: latest.message }),
        ...(latest.error === undefined ? {} : { error: latest.error }),
        ...(latest.processDeath === true ? { processDeath: true } : {}),
    };
}
function boundExecution(write) {
    const error = write.error === undefined
        ? undefined
        : {
            name: boundedText(write.error.name, 128),
            message: boundedText(write.error.message, MAX_ERROR_MESSAGE_CHARS),
            ...(write.error.stack === undefined
                ? {}
                : {
                    stack: boundedText(write.error.stack, MAX_ERROR_STACK_CHARS),
                }),
        };
    return {
        executionId: write.executionId,
        writtenAt: write.writtenAt,
        sessionId: write.sessionId,
        turnStatus: write.turnStatus,
        durationMs: write.durationMs,
        ...(write.abortReason === undefined ? {} : { abortReason: write.abortReason }),
        ...(boundedOptionalText(write.message, MAX_ERROR_MESSAGE_CHARS) === undefined
            ? {}
            : {
                message: boundedOptionalText(write.message, MAX_ERROR_MESSAGE_CHARS),
            }),
        ...(error === undefined ? {} : { error }),
        ...(write.processDeath === true ? { processDeath: true } : {}),
        logs: snapshotSessionRunLogs(write.logs),
    };
}
function upsertExecution(existing, next) {
    const executions = existing.filter((entry) => entry.executionId !== next.executionId);
    executions.push(next);
    executions.sort((a, b) => a.writtenAt.localeCompare(b.writtenAt));
    return executions.slice(-SESSION_RUN_LOG_MAX_EXECUTIONS);
}
function shrinkSessionDocument(document) {
    let executions = document.executions;
    let next = {
        ...document,
        executions,
        lastFailure: lastFailureFromExecutions(executions),
    };
    let serialized = JSON.stringify(next);
    while (serialized.length > MAX_DOCUMENT_CHARS) {
        const oldestWithLogs = executions.findIndex((entry) => entry.logs.length > 0);
        if (oldestWithLogs >= 0) {
            const entry = executions[oldestWithLogs];
            executions = executions.map((item, index) => index === oldestWithLogs
                ? {
                    ...entry,
                    logs: entry.logs.slice(Math.ceil(entry.logs.length / 2)),
                }
                : item);
        }
        else if (executions.length > 1) {
            executions = executions.slice(1);
        }
        else {
            break;
        }
        next = {
            ...document,
            executions,
            lastFailure: lastFailureFromExecutions(executions),
        };
        serialized = JSON.stringify(next);
    }
    return next;
}
export function parseSessionRunLogDocument(value) {
    if (!isRecord(value) || value.v !== SESSION_RUN_LOG_VERSION) {
        return undefined;
    }
    const sessionPublicId = typeof value.sessionPublicId === "string" ? value.sessionPublicId : undefined;
    const updatedAt = typeof value.updatedAt === "string" ? value.updatedAt : undefined;
    if (sessionPublicId === undefined ||
        sessionPublicId.length === 0 ||
        updatedAt === undefined ||
        !Array.isArray(value.executions)) {
        return undefined;
    }
    const executions = [];
    for (const entry of value.executions) {
        const parsed = parseExecution(entry);
        if (parsed !== undefined) {
            executions.push(parsed);
        }
    }
    executions.sort((a, b) => a.writtenAt.localeCompare(b.writtenAt));
    const lastFailure = lastFailureFromExecutions(executions);
    return {
        v: SESSION_RUN_LOG_VERSION,
        sessionPublicId,
        updatedAt,
        ...(lastFailure === undefined ? {} : { lastFailure }),
        executions,
    };
}
export function createSessionRunLogStore(input) {
    const { sink, agentName } = input;
    const logger = input.logger ?? (() => { });
    let active;
    const readDocument = async (sessionPublicId) => {
        const key = agentSdkStorageKeys.sessionRun(agentName, sessionPublicId);
        const body = await sink.get(key);
        if (body === undefined) {
            return undefined;
        }
        try {
            return parseSessionRunLogDocument(JSON.parse(new TextDecoder().decode(decodeSinkBody(body))));
        }
        catch (error) {
            logger(`[bdk] session-run log: skip unreadable ${key} (${describeError(error)})`);
            return undefined;
        }
    };
    const persistWrite = async (write) => {
        const fitted = boundExecution(write);
        // Stamped before the store round trip: the turn no longer waits for this
        // write, and a crash while it is in flight still needs an execution to
        // record.
        if (fitted.turnStatus === "running") {
            active = {
                sessionPublicId: write.sessionPublicId,
                executionId: fitted.executionId,
                sessionId: fitted.sessionId,
                startedAt: active?.executionId === fitted.executionId ? active.startedAt : Date.now(),
            };
        }
        let existing;
        try {
            existing = await readDocument(write.sessionPublicId);
        }
        catch (error) {
            logger(`[bdk] session-run log: persist failed for ${fitted.executionId} (${describeError(error)})`);
            return;
        }
        const executions = upsertExecution(existing?.executions ?? [], fitted);
        const document = shrinkSessionDocument({
            v: SESSION_RUN_LOG_VERSION,
            sessionPublicId: write.sessionPublicId,
            updatedAt: fitted.writtenAt,
            executions,
        });
        const key = agentSdkStorageKeys.sessionRun(agentName, document.sessionPublicId);
        try {
            await sink.put(key, new TextEncoder().encode(JSON.stringify(document)));
        }
        catch (error) {
            logger(`[bdk] session-run log: persist failed for ${fitted.executionId} (${describeError(error)})`);
            return;
        }
        if (fitted.turnStatus !== "running" && active?.executionId === fitted.executionId) {
            active = undefined;
        }
    };
    const inflight = new Set();
    const trackedPersist = (write) => {
        const run = persistWrite(write);
        inflight.add(run);
        void run.finally(() => inflight.delete(run));
        return run;
    };
    return {
        persist: trackedPersist,
        async read(sessionPublicId) {
            try {
                return await readDocument(sessionPublicId);
            }
            catch (error) {
                logger(`[bdk] session-run log: read failed for ${sessionPublicId} (${describeError(error)})`);
                return undefined;
            }
        },
        async flushProcessDeath(reason, error) {
            if (active === undefined) {
                return;
            }
            const current = active;
            // A `running` put still in flight would otherwise land after this
            // record and overwrite it. The caller bounds the wait.
            await Promise.allSettled([...inflight]);
            if (active?.executionId !== current.executionId) {
                return;
            }
            const serialized = error === undefined ? undefined : serializeSessionRunError(error);
            const message = error instanceof Error
                ? error.message
                : typeof error === "string"
                    ? error
                    : typeof error === "number" || typeof error === "boolean"
                        ? String(error)
                        : "process died during hosted execution";
            await persistWrite({
                sessionPublicId: current.sessionPublicId,
                executionId: current.executionId,
                writtenAt: new Date().toISOString(),
                sessionId: current.sessionId,
                turnStatus: "error",
                durationMs: Math.max(0, Date.now() - current.startedAt),
                abortReason: reason,
                processDeath: true,
                message,
                ...(serialized === undefined ? {} : { error: serialized }),
                logs: snapshotSessionRunLogs(input.snapshotLogs?.() ?? []),
            });
        },
    };
}
/**
 * Enable durable execution history for architecture-v2 agents on
 * Cursor-managed hosting. Self-hosted and architecture-v1 agents keep local
 * behavior.
 */
export function selectSessionRunLogStore(input) {
    const hosting = resolveAgentV2Hosting({
        architecture: input.project.agent.architecture,
        env: input.env,
    });
    if (!isCursorManagedV2Hosting(hosting)) {
        return undefined;
    }
    return createSessionRunLogStore({
        sink: cursorHostedFiles({
            resolveStoreSourceId: () => hosting.resolveStoreIds().frameworkStoreSourceId,
            resolveApiKey: () => resolveApiKeySync()?.apiKey,
        }),
        agentName: input.project.name,
        logger: input.logger,
        ...(input.snapshotLogs === undefined ? {} : { snapshotLogs: input.snapshotLogs }),
    });
}
